return ['project-id-version'=>'PN Scripts Tabcrest 1.0.4','report-msgid-bugs-to'=>'https://github.com/pnscripts/pnscripts-tabcrest/issues','last-translator'=>'PN Scripts <https://pnscripts.com>','language-team'=>'Bulgarian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','po-revision-date'=>'2026-10-04 00:00+0000','x-generator'=>'WP-CLI 2.12.0','x-domain'=>'pnscripts-tabcrest','language'=>'bg_BG','plural-forms'=>'nplurals=2; plural=(n != 1);','messages'=>['%d product with YIKES tabs'=>'%d продукт с раздели от YIKES' . "\0" . '%d продукта с раздели от YIKES','(deleted global tab)'=>'(изтрит глобален раздел)','(no title)'=>'(без заглавие)','Add'=>'Добави','Add FAQ tab'=>'Добави раздел с ЧЗВ','Add a global tab…'=>'Добави глобален раздел…','Add global tab'=>'Добави глобален раздел','Add question'=>'Добави въпрос','Add tab'=>'Добави раздел','Additional information'=>'Допълнителна информация','All products'=>'Всички продукти','Answer'=>'Отговор','Categories (subcategories included)'=>'Категории (включително подкатегориите)','Choose categories…'=>'Изберете категории…','Choose tags…'=>'Изберете етикети…','Content comes from the global tab and updates everywhere when you edit it.'=>'Съдържанието идва от глобалния раздел и се обновява навсякъде, когато го редактирате.','Copies the tabs of "Custom Product Tabs for WooCommerce" by YIKES: every product\'s tabs (in the same order, with the same content) and the saved tabs, which become global tabs. Products that used a saved tab are linked to the new global tab, so editing it updates them all. Saved tabs that the YIKES Pro add-on assigned to all products or to categories/tags keep those rules.'=>'Копира разделите на „Custom Product Tabs for WooCommerce“ от YIKES: разделите на всеки продукт (в същия ред и със същото съдържание) и запазените раздели, които стават глобални. Продуктите, използвали запазен раздел, се свързват с новия глобален раздел, така че редакцията му обновява всички. Запазените раздели, които YIKES Pro е задал за всички продукти или за категории/етикети, запазват тези правила.','Custom product tabs per product, reusable global tabs by category or tag, FAQ tabs with optional FAQPage schema, rename, reorder or hide the default tabs, and a one-click importer from YIKES Custom Product Tabs. Works in classic and block themes.'=>'Собствени раздели за всеки продукт, глобални раздели за категории или етикети, раздели с ЧЗВ и FAQPage schema, преименуване, подреждане и скриване на стандартните раздели и импорт с едно кликване от YIKES Custom Product Tabs. Работи с класически и блокови теми.','Custom tabs'=>'Собствени раздели','Default tabs YIKES replaced (hidden on those products)'=>'Стандартни раздели, заменени от YIKES (скрити на тези продукти)','Delete all tabs and settings of this plugin when it is deleted from the Plugins screen'=>'Изтрий всички раздели и настройки на това разширение, когато бъде изтрито от екрана Разширения','Description'=>'Описание','Dismiss'=>'Скрий','Display'=>'Показване','Drag to reorder'=>'Плъзнете, за да пренаредите','Dry run (change nothing)'=>'Пробно изпълнение (без промени)','Dry run finished: nothing was changed. These numbers are what an import will do.'=>'Пробното изпълнение приключи: нищо не е променено. Тези числа показват какво ще направи импортът.','Edit global tab'=>'Редактирай глобалния раздел','FAQ'=>'ЧЗВ','FAQ: questions and answers below'=>'ЧЗВ: въпросите и отговорите по-долу','Found:'=>'Намерени:','Global'=>'Глобален','Global product tab'=>'Глобален продуктов раздел','Global product tabs'=>'Глобални продуктови раздели','Global tab published.'=>'Глобалният раздел е публикуван.','Global tab to add'=>'Глобален раздел за добавяне','Global tab updated.'=>'Глобалният раздел е обновен.','Global tabs'=>'Глобални раздели','Global tabs shown automatically'=>'Глобални раздели, показвани автоматично','Global tabs to create / created'=>'Глобални раздели за създаване / създадени','Hide "%s" on this product'=>'Скрий „%s“ на този продукт','Import finished. Check a few product pages, then deactivate YIKES Custom Product Tabs.'=>'Импортът приключи. Проверете няколко продуктови страници и след това деактивирайте YIKES Custom Product Tabs.','Import from YIKES'=>'Импорт от YIKES','Import now'=>'Импортирай сега','Import removed.'=>'Импортът е премахнат.','Import the YIKES tabs now? YIKES data is not changed and you can undo the import.'=>'Да се импортират ли разделите от YIKES сега? Данните на YIKES не се променят и можете да отмените импорта.','Imported'=>'Импортиран','Imported global tabs removed'=>'Премахнати импортирани глобални раздели','Keep Reviews as the last tab'=>'Отзиви винаги като последен раздел','Large catalogues are handled in batches of 100 products. Command line: wp pnscripts-tabcrest import-yikes --dry-run'=>'Големите каталози се обработват на партиди по 100 продукта. Команден ред: wp pnscripts-tabcrest import-yikes --dry-run','Lower numbers come first. WooCommerce uses 10 for Description, 20 for Additional information and 30 for Reviews (change these under Products → Tab settings).'=>'По-малките числа са първи. WooCommerce използва 10 за Описание, 20 за Допълнителна информация и 30 за Отзиви (променят се в Продукти → Настройки на разделите).','Manage global tabs'=>'Управление на глобалните раздели','New global tab'=>'Нов глобален раздел','No categories or tags chosen'=>'Няма избрани категории или етикети','No custom tabs on this product yet.'=>'Този продукт още няма собствени раздели.','No global tabs in the trash.'=>'Няма глобални раздели в кошчето.','No global tabs yet.'=>'Още няма глобални раздели.','Notes'=>'Бележки','Off by default, so deleting and reinstalling the plugin keeps your tabs. YIKES data is never touched.'=>'Изключено по подразбиране, така че изтриването и повторното инсталиране запазва разделите. Данните на YIKES никога не се променят.','Only products where I add it (Product data → Custom tabs)'=>'Само продукти, в които го добавя (Данни за продукта → Собствени раздели)','Output FAQPage structured data for FAQ tabs that allow it (turn off if your SEO plugin already adds FAQ markup)'=>'Извеждай структурирани данни FAQPage за разделите с ЧЗВ, които го позволяват (изключете, ако SEO разширението ви вече добавя FAQ маркиране)','PN Scripts'=>'PN Scripts','PN Scripts Tabcrest found tabs from Custom Product Tabs for WooCommerce (YIKES). Import them in one click; YIKES data stays untouched.'=>'PN Scripts Tabcrest откри раздели от Custom Product Tabs for WooCommerce (YIKES). Импортирайте ги с едно кликване; данните на YIKES остават непокътнати.','PN Scripts Tabcrest needs WooCommerce %s or newer to be active.'=>'PN Scripts Tabcrest изисква активен WooCommerce %s или по-нов.','PN Scripts Tabcrest – Custom Product Tabs & FAQ'=>'PN Scripts Tabcrest – Custom Product Tabs & FAQ','Position (priority)'=>'Позиция (приоритет)','Priority'=>'Приоритет','Priority of product tabs'=>'Приоритет на продуктовите раздели','Product #%1$d: the tab "%2$s" was hidden by a later tab with the same title in YIKES; it was imported switched off.'=>'Продукт №%1$d: разделът „%2$s“ е бил скрит от по-късен раздел със същото заглавие в YIKES; импортиран е изключен.','Product #%d: a tab without a title (never shown by YIKES) was imported switched off.'=>'Продукт №%d: раздел без заглавие (никога не показван от YIKES) е импортиран изключен.','Product tab settings'=>'Настройки на продуктовите раздели','Product tabs'=>'Продуктови раздели','Product tabs copied'=>'Копирани продуктови раздели','Product tabs linked to a global tab'=>'Продуктови раздели, свързани с глобален раздел','Products cleaned'=>'Почистени продукти','Products in these categories or with these tags'=>'Продукти в тези категории или с тези етикети','Products to import / imported'=>'Продукти за импорт / импортирани','Products unchanged since the last import (skipped)'=>'Продукти без промяна от последния импорт (пропуснати)','Products where added'=>'Продукти, в които е добавен','Products with YIKES tabs'=>'Продукти с раздели от YIKES','Publish as FAQPage structured data'=>'Публикувай като структурирани данни FAQPage','Question'=>'Въпрос','Remove'=>'Премахни','Remove all tabs created by the import (tabs you added yourself stay)?'=>'Да се премахнат ли всички раздели, създадени от импорта (добавените от вас остават)?','Remove question'=>'Премахни въпроса','Remove this tab? It is deleted when you update the product.'=>'Да се премахне ли разделът? Изтрива се, когато обновите продукта.','Rename, reorder or hide the standard tabs on every product (single products can hide them too, under Product data → Custom tabs). Leave a title empty to keep WooCommerce\'s title; in the Reviews title, %s becomes the number of reviews.'=>'Преименувайте, пренаредете или скрийте стандартните раздели на всички продукти (отделни продукти също могат да ги скрият в Данни за продукта → Собствени раздели). Оставете заглавието празно, за да запазите заглавието на WooCommerce; в заглавието на Отзиви %s се заменя с броя на отзивите.','Repeat the tab title as a heading inside the tab (classic tabs; never inside accordions)'=>'Повтаряй заглавието като заглавие в раздела (класически раздели; никога в акордеони)','Reusable tabs shown on all products, on products in chosen categories or tags, or where added manually.'=>'Раздели за многократна употреба, показвани на всички продукти, на продукти в избрани категории или етикети, или там, където са добавени ръчно.','Review the import'=>'Прегледай импорта','Reviews'=>'Отзиви','Rich text'=>'Текст','Rich text: the content written in the editor above'=>'Текст: съдържанието от редактора по-горе','Running it again is safe: tabs are never duplicated, and products whose YIKES tabs did not change are skipped.'=>'Повторното изпълнение е безопасно: разделите не се дублират, а продуктите без промени в YIKES се пропускат.','Saved tab "%1$s" was assigned by the taxonomy "%2$s", which is not supported; it is imported for the categories and tags only.'=>'Запазеният раздел „%1$s“ е бил зададен по таксономията „%2$s“, която не се поддържа; импортира се само за категориите и етикетите.','Saved tab #%d has no title and was skipped.'=>'Запазеният раздел №%d няма заглавие и е пропуснат.','Saved tabs imported before (left as they are)'=>'Запазени раздели, импортирани преди (остават непроменени)','Search global tabs'=>'Търси в глобалните раздели','Settings'=>'Настройки','Show'=>'Показвай','Show this tab on'=>'Показвай раздела на','Shown on'=>'Показва се на','Sorry, you are not allowed to view global product tabs.'=>'Нямате права да преглеждате глобалните продуктови раздели.','Tab'=>'Раздел','Tab content'=>'Съдържание на раздела','Tab settings'=>'Настройки на разделите','Tab title'=>'Заглавие на раздела','Tab type'=>'Вид на раздела','Tabs YIKES never showed (no title, or hidden by another tab with the same title) are imported switched off and listed below.'=>'Разделите, които YIKES никога не е показвал (без заглавие или скрити от друг раздел със същото заглавие), се импортират изключени и са изброени по-долу.','Tabs hidden by a duplicate title in YIKES (imported switched off)'=>'Раздели, скрити от дублирано заглавие в YIKES (импортирани изключени)','Tabs shown on this product, in this order (drag to reorder). Rich-text tabs accept anything the editor does; FAQ tabs show questions as an accessible list and can publish FAQPage structured data.'=>'Раздели на този продукт в този ред (плъзнете, за да пренаредите). Текстовите раздели приемат всичко, което поддържа редакторът; разделите с ЧЗВ показват въпросите като достъпен списък и могат да публикуват структурирани данни FAQPage.','Tabs without a title (imported switched off)'=>'Раздели без заглавие (импортирани изключени)','Tags'=>'Етикети','The first tab added on a product gets this priority, the next one +1, and so on. 25 places them between Additional information and Reviews. Global tabs have their own priority.'=>'Първият раздел на продукта получава този приоритет, следващият +1 и т.н. 25 ги поставя между Допълнителна информация и Отзиви. Глобалните раздели имат собствен приоритет.','The request failed. Reload the page and try again.'=>'Заявката беше неуспешна. Презаредете страницата и опитайте отново.','Title'=>'Заглавие','Type'=>'Вид','Undo import'=>'Отмени импорта','Uninstall'=>'Деинсталиране','While YIKES Custom Product Tabs is still active, hide its copy of tabs that were imported'=>'Докато YIKES Custom Product Tabs е активен, скривай неговото копие на импортираните раздели','WooCommerce tabs'=>'Раздели на WooCommerce','WooCommerce tabs on this product'=>'Раздели на WooCommerce в този продукт','Working… %d products handled'=>'Обработка… %d обработени продукта','YIKES data is only read. Nothing is changed or deleted, and YIKES keeps working until you deactivate it.'=>'Данните на YIKES само се четат. Нищо не се променя или изтрива и YIKES продължава да работи, докато не го деактивирате.','YIKES plugin active'=>'разширението YIKES е активно','YIKES plugin not active (data can still be imported)'=>'разширението YIKES не е активно (данните пак могат да се импортират)','YIKES saved tabs'=>'Запазени раздели в YIKES','You are not allowed to import tabs.'=>'Нямате права да импортирате раздели.','https://pnscripts.com'=>'https://pnscripts.com','https://pnscripts.com/marketplace/pnscripts-tabcrest'=>'https://pnscripts.com/marketplace/pnscripts-tabcrest','last import: %s'=>'последен импорт: %s','… and %d more notes like these.'=>'… и още %d подобни бележки.']];
